with open('/home/ubuntu/.agent-ml-research-idea_gen_0520_2/projects/irt_equated_bench_regen/logs/workers/worker_code_mf2_practical_significance_20260522T020934.log', 'r') as f:
    lines = f.readlines()

for i, line in enumerate(lines, 1):
    try:
        data = json.loads(line)

        # Extract thinking content
        if data.get('type') == 'assistant':
            for item in data.get('message', {}).get('content', []):
                if item.get('type') == 'thinking':
                    print(f"=== THINKING (line {i}) ===")
                    print(item.get('thinking', '')[:500])

        # Extract tool calls
        if data.get('type') == 'assistant':
            for item in data.get('message', {}).get('content', []):
                if item.get('type') == 'tool_use':
                    print(f"\n=== TOOL CALL (line {i}) ===")
                    print(f"Tool: {item.get('name')}")
                    print(f"Command: {item.get('input', {}).get('command', '')[:200]}")

    except json.JSONDecodeError:
        pass
